from .devices.hbte.hbte import HBTE
from .devices.hbte.hbte_ppsam_64_16_23_38_90_05_360_1_a import HBTEPPSAM6416233890053601A
from .devices.hbte.hbte_ppsam_64_16_23_5_90_05_360_1_a import HBTEPPSAM641623590053601A
from .devices.hbte.hbte_ppsam_64_16_23_5_90_05_360_1_s import HBTEPPSAM641623590053601S
from .devices.topyoung.topyoung import Topyoung
from .devices.topyoung.topyoung_mcs2338a2_64b16_a1 import TOPYOUNGMCS2338A264B16A1
from .devices.topyoung.topyoung_mcs2338a2_64b16_a4 import TOPYOUNGMCS2338A264B16A4
from .devices.topyoung.topyoung_mcs2338a2_64b16_b4 import TOPYOUNGMCS2338A264B16B4
from .devices.topyoung.topyoung_mcs2350a2_128b16_e6 import TOPYOUNGMCS2350A2128B16E6
from .devices.topyoung.topyoung_mcs2350a2_64b16_a4 import TOPYOUNGMCS2350A264B16A4
from .devices.topyoung.topyoung_mcs2350a2_64b16_a5 import TOPYOUNGMCS2350A264B16A5
from .devices.topyoung.topyoung_mcs2350a2_128b16_a4 import TOPYOUNGMCS2350A2128B16A4
from .devices.topyoung.topyoung_mcs2350a2_128b16_a5 import TOPYOUNGMCS2350A2128B16A5
from .devices.topyoung.topyoung_mcs2350a2_64b16_e6 import TOPYOUNGMCS2350A264B16E6
from .devices.topyoung.topyoung_mcs2350a2_64b16_b1 import TOPYOUNGMCS2350A264B16B1
from .devices.topyoung.topyoung_mcs2350a2_64b32_e6 import TOPYOUNGMCS2350A264B32E6
from taf.hw.mcs.devices.haojin import HaoJin, HaoJinRadioPsa64x161024
from .exception import MCSNotSupported


class MCSFactory(object):

    _supported_mcs = [HBTE, HBTEPPSAM6416233890053601A,
                      HBTEPPSAM641623590053601A, HBTEPPSAM641623590053601S,
                      Topyoung, TOPYOUNGMCS2338A264B16A1, TOPYOUNGMCS2338A264B16A4, TOPYOUNGMCS2338A264B16B4,
                      TOPYOUNGMCS2350A2128B16E6, HaoJin, HaoJinRadioPsa64x161024, TOPYOUNGMCS2350A264B16A4,
                      TOPYOUNGMCS2350A2128B16A4, TOPYOUNGMCS2350A264B16E6, TOPYOUNGMCS2350A2128B16A5,
                      TOPYOUNGMCS2350A264B16B1, TOPYOUNGMCS2350A264B32E6, TOPYOUNGMCS2350A264B16A5]

    @classmethod
    def create(cls, vendor, model=None, version=None, **kwargs):
        mcs_cls = cls._find_mcs(vendor, model, version)
        return mcs_cls(**kwargs)

    @classmethod
    def _find_mcs(cls, vendor, model, version):
        for mcs in MCSFactory._supported_mcs:
            vendor = vendor.upper() if vendor else None
            model = model.upper() if model else None
            version = version.upper() if version else None

            if mcs.get_vendor() == vendor and mcs.get_model() == model and mcs.get_version() == version:
                return mcs
        else:
            raise MCSNotSupported("not found matched mcs")
